export function getBlogPost(slug: string): BlogPost | undefined {
  return BLOG_POSTS.find((p) => p.slug === slug || p.alias === slug);
}

export function getAllBlogSlugs(): string[] {
  const slugs: string[] = [];
  BLOG_POSTS.forEach((p) => {
    slugs.push(p.slug);
    if (p.alias) slugs.push(p.alias);
  });
  return slugs;
}
